import json,sys,collections,math,time
sys.path.insert(0,'scripts')
from cost_model import CostModel,align,HEADS,HIDDEN,CostConsts
C=CostConsts(); cm=CostModel(64); H=HIDDEN
A=C.Kd_attn; B=C.Kd_mlp*H
def load(f): return [json.loads(l) for l in open(f)]
def sum_sq(a,n): return n*a*a+a*n*(n-1)+n*(n-1)*(2*n-1)//6
def sum_lin(a,n): return n*a+n*(n-1)/2
def dc(S,g): return A*sum_sq(S,g)+B*sum_lin(S,g)
def dl(S,g): return C.Td_attn*sum_sq(S,g)+C.Td_mlp*H*sum_lin(S,g)
def pl(S): return C.Tp_attn*S*S+C.Tp_mlp*S*H
def cc(S): return C.Kshape_attn*S*S + C.Kshape_mlp*S*H
def gbmap(gen,w,off=0): return max(1,math.ceil((gen-off)/w))*w+off

def optimize2(reqs,w,off=0,K=8):
    # cells: s -> gb -> count
    cells=collections.defaultdict(lambda: collections.Counter())
    for r in reqs:
        s=align(r['prompt_len'],64); cells[s][gbmap(r['gen_len'],w,off)]+=1
    seqs=sorted(cells); m=len(seqs); INF=float('inf')
    mcost=[[0.0]*m for _ in range(m)]; mseq=[[0.0]*m for _ in range(m)]
    for i in range(m):
        cnt=collections.Counter(); mx={}
        for j in range(i,m):
            s=seqs[j]
            for gb,n in cells[s].items():
                cnt[gb]+=n; mx[gb]=max(mx.get(gb,0),s)
            c=0.0; sq=0.0
            for gb,n in cnt.items():
                c+=n*dc(mx[gb],gb)
                sq+=pl(mx[gb])+dl(mx[gb],gb)+8
            c+=1e7*len(cnt)
            mcost[i][j]=c; mseq[i][j]=sq
    dp=[[INF]*m for _ in range(K+1)]; par=[[-1]*m for _ in range(K+1)]
    for j in range(m): dp[1][j]=mcost[0][j]+cc(seqs[j]); par[1][j]=-1
    for k in range(2,K+1):
        for j in range(m):
            best=INF;bi=-1
            for i in range(1,j+1):
                v=dp[k-1][i-1]+mcost[i][j]+cc(seqs[j])
                if v<best: best=v;bi=i-1
            dp[k][j]=best;par[k][j]=bi
    bestk=min(range(1,K+1),key=lambda k:dp[k][m-1]); best=dp[bestk][m-1]
    groups=[];k=bestk;j=m-1
    while j>=0:
        i=par[k][j]+1 if par[k][j]!=-1 else 0
        groups.append((i,j));j=i-1;k-=1
    groups.reverse()
    reps=[seqs[j] for i,j in groups]
    return best,reps,groups,seqs

def eval_groups(reqs,groups,seqs,w,off=0,labels=None):
    reps=[seqs[j] for i,j in groups]
    if labels is None: labels=sorted(set(reps))
    labels=sorted(labels)
    def lab(s): return next((x for x in labels if x>=s),labels[-1])
    byreq={r['request_id']:r for r in reqs}
    gp=collections.defaultdict(list)
    for r in reqs:
        s=align(r['prompt_len'],64)
        gi=next(k for k,(i,j) in enumerate(groups) if seqs[i]<=s<=seqs[j])
        gp[(gi,gbmap(r['gen_len'],w,off))].append(r)
    recs=[];bid=0
    for (gi,g),rs in sorted(gp.items()):
        bid+=1;b=f'b-{bid:04d}'
        smax=max(align(r['prompt_len'],64) for r in rs)
        for r in rs: recs.append({'request_id':r['request_id'],'batch_id':b,'shape':{'seq_align':lab(smax),'heads_align':HEADS,'hidden_align':HIDDEN}})
    return cm.plan_metrics(byreq,recs),len(gp),reps

if __name__=='__main__':
    for f in ['input_data/requests_bucket_1.jsonl','input_data/requests_bucket_2.jsonl']:
        reqs=load(f); print('\n',f)
        for w in [1,2,3,4,5,6,7,8,10,12,16]:
            best,reps,go,seqs=optimize2(reqs,w)
            m,nb,_=eval_groups(reqs,go,seqs,w)
            print('w=%2d reps=%s batches=%d cost=%.5e pad=%.5f p95=%.4e seq=%.4e dp=%.4e'%(w,reps,nb,m['cost'],m['pad_ratio'],m['p95_latency_ms'],m['sequential_timecost'],best))
