import json,sys,collections,math
sys.path.insert(0,'scripts');
from dp2 import load,dc,dl,pl,gbmap,align,C,HEADS,HIDDEN
from cost_model import CostModel
cm=CostModel(64)
def optimize3(reqs,w,off=0,Kmax=24):
    cells=collections.defaultdict(lambda: collections.Counter())
    for r in reqs:
        s=align(r['prompt_len'],64); cells[s][gbmap(r['gen_len'],w,off)]+=1
    seqs=sorted(cells); m=len(seqs); INF=float('inf')
    mcost=[[0.0]*m for _ in range(m)]
    for i in range(m):
