        for j in range(i,m):
            s=seqs[j]
            for gb,n in cells[s].items():
                cnt[gb]+=n; mx[gb]=max(mx.get(gb,0),s)
            c=0.0
            for gb,n in cnt.items(): c+=n*dc(mx[gb],gb)
            c+=1e7*len(cnt)
            mcost[i][j]=c
    Kmax=min(Kmax,m)
    dp=[[INF]*m for _ in range(Kmax+1)]; par=[[-1]*m for _ in range(Kmax+1)]
    for j in range(m): dp[1][j]=mcost[0][j]; par[1][j]=-1
    for k in range(2,Kmax+1):
        for j in range(m):
            best=INF;bi=-1
            for i in range(1,j+1):
                v=dp[k-1][i-1]+mcost[i][j]
                if v<best: best=v;bi=i-1
            dp[k][j]=best;par[k][j]=bi
    bestk=min(range(1,Kmax+1),key=lambda k:dp[k][m-1]); best=dp[bestk][m-1]
    groups=[];k=bestk;j=m-1
    while j>=0:
        i=par[k][j]+1 if par[k][j]!=-1 else 0
        groups.append((i,j));j=i-1;k-=1
    groups.reverse()
    return best,[seqs[j] for i,j in groups],groups,seqs

def eval3(reqs,groups,seqs,w,off,label):
