        bid+=1;b=f'b-{bid:04d}'
        for r in rs: recs.append({'request_id':r['request_id'],'batch_id':b,'shape':{'seq_align':label,'heads_align':HEADS,'hidden_align':HIDDEN}})
    return cm.plan_metrics(byreq,recs),len(gp)

if __name__=='__main__':
    for f,label in [('input_data/requests_bucket_1.jsonl',2048),('input_data/requests_bucket_2.jsonl',704)]:
