        for w in range(4,25):
            for off in range(w):
                best,reps,go,seqs=optimize3(reqs,w,off,Kmax=24)
                m,nb=eval3(reqs,go,seqs,w,off,label)
                ok=(m['cost']<(3e11 if '1' in f else 4.8e10) and m['pad_ratio']<(.055 if '1' in f else .15) and m['p95_latency_ms']<(2.1e6 if '1' in f else 2.1e5) and m['sequential_timecost']<(2.7e8 if '1' in f else 3.2e7))
                if ok:
