                    print('w=%2d off=%2d nb=%3d groups=%2d cost=%.6e pad=%.6f p95=%.4e seq=%.4e'%(w,off,nb,len(go),m['cost'],m['pad_ratio'],m['p95_latency_ms'],m['sequential_timecost']))
